public class BankAccount {
    private int balance = 1000;

    // Synchronized method - locks on 'this' object
    public synchronized void withdraw(int amount) {
        if (balance >= amount) {
            balance -= amount; // Critical section protected
        }
    }

    // Synchronized block - explicit lock object
    private final Object balanceLock = new Object();

    public void deposit(int amount) {
        synchronized(balanceLock) { // Lock only this section
            balance += amount;
        }
        System.out.println("Deposit complete"); // Runs without lock
    }

    // Static synchronized - locks on BankAccount.class object
    private static int totalAccounts = 0;

    public static synchronized void incrementAccounts() {
        totalAccounts++; // Class-level lock
    }
}
