public class VisitorCounter {
    private int count = 0; // Shared mutable state

    // UNSAFE: Race condition - multiple threads interleave read-modify-write
    public void incrementUnsafe() {
        count++; // Three CPU instructions: read, add, write
    }

    // SAFE: synchronized prevents interleaving
    public synchronized void incrementSafe() {
        count++; // Only one thread executes this at a time
    }

    public synchronized int getCount() {
        return count;
    }
}

// Simulate race condition
var counter = new VisitorCounter();
var threads = List.of(
    new Thread(() -> { for (int i = 0; i < 1000; i++) counter.incrementUnsafe(); }),
    new Thread(() -> { for (int i = 0; i < 1000; i++) counter.incrementUnsafe(); })
);
threads.forEach(Thread::start);
threads.forEach(t -> { try { t.join(); } catch (InterruptedException e) {} });
System.out.println(counter.getCount()); // Expected 2000, might get 1850
