public class BankAccount {
    private final long id;
    private int balance;

    public BankAccount(long id, int balance) {
        this.id = id;
        this.balance = balance;
    }

    // DEADLOCK PRONE: Inconsistent lock ordering
    public void transferUnsafe(BankAccount to, int amount) {
        synchronized(this) { // Lock source account
            synchronized(to) { // Then lock destination - ORDER VARIES
                this.balance -= amount;
                to.balance += amount;
            }
        }
    }

    // DEADLOCK SAFE: Consistent lock ordering by account ID
    public void transferSafe(BankAccount to, int amount) {
        BankAccount first = this.id < to.id ? this : to;
        BankAccount second = this.id < to.id ? to : this;

        synchronized(first) { // Always lock lower ID first
            synchronized(second) {
                this.balance -= amount;
                to.balance += amount;
            }
        }
    }
}
