public class VisibilityDemo {
    private boolean ready = false; // Not volatile - visibility issue
    private int value = 0;

    // Thread 1: Writer - may cache writes
    public void writer() {
        value = 42;
        ready = true; // Other threads might never see this
    }

    // Thread 2: Reader - may cache reads
    public void reader() {
        while (!ready) { // Might loop forever seeing cached false
            Thread.yield();
        }
        System.out.println(value); // Might print 0 due to stale cache
    }

    // FIXED with synchronized - guarantees visibility
    private final Object lock = new Object();

    public void writerSafe() {
        synchronized(lock) {
            value = 42;
            ready = true; // Cache flushed when lock released
        }
    }

    public void readerSafe() {
        synchronized(lock) { // Cache invalidated when lock acquired
            while (!ready) Thread.yield();
            System.out.println(value); // Guaranteed to see 42
        }
    }
}
